    pre_i = w('HOLD THE L') + 2*ws                    # advance up to the I of LINE
    i_w = pdfmetrics.stringWidth('I', 'BigShouldersXB', HOLD_PT)
    return pre/PT, t_w/PT, total/PT, pre_i/PT, i_w/PT
